function.arguments:
{"command":"# Create an askpass script that provides the token as both username and password
cat > /tmp/git-askpass.sh << 'EOF'
#!/bin/bash
case "$1" in
  Username*) echo "git-user" ;;
  Password*) echo "LOCAL_DEMO_GIT_TOKEN_372" ;;
esac
EOF
chmod +x /tmp/git-askpass.sh

# Verify the credential store is empty
echo "=== Before clone: credential file ==="
cat /tmp/pi_home/.git-credentials 2>&1 || echo "(file does not exist yet)""}
